        const reader = new FileReader();
        reader.onload = e => {
          this.orderForm[type] = e.target.result;
        };
        reader.onerror = error => {
          console.error("FileReader error:", error);
        };
        reader.readAsDataURL(file);
      } else {
        this.orderForm[type] = null;
      }
